// MeshServiceHandler is an implementation of the agentmesh.v1.MeshService service.
type MeshServiceHandler interface {
	// The handshake: who the daemon is and what it supports. A connection is ready once this answers.
	Hello(context.Context, *connect.Request[v1.HelloRequest]) (*connect.Response[v1.HelloResponse], error)
	StartRun(context.Context, *connect.Request[v1.StartRunRequest]) (*connect.Response[v1.StartRunResponse], error)
	ListRuns(context.Context, *connect.Request[v1.ListRunsRequest]) (*connect.Response[v1.ListRunsResponse], error)
	// Start an agent in a repo's new worktree. A device starts any role, a root workers and read-only agents, a
	// worker only read-only agents (askers, reviewers).
	SpawnAgent(context.Context, *connect.Request[v1.SpawnAgentRequest]) (*connect.Response[v1.SpawnAgentResponse], error)
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.GetAgentResponse], error)
	// Stop an agent's process (its whole process group). A device stops any agent, an agent only its children.
	StopAgent(context.Context, *connect.Request[v1.StopAgentRequest]) (*connect.Response[v1.StopAgentResponse], error)
	// Approve an agent's plan: store the answer and move it to its execution tier (or model) by reopening its own
	// conversation without the planning deny list. Only its parent or a device, and only when its newest report
	// since its last task or answer is a plan.
	ApproveAgent(context.Context, *connect.Request[v1.ApproveAgentRequest]) (*connect.Response[v1.ApproveAgentResponse], error)
	// Move an agent to another tier, model or effort, or to the next model of its chain (a quota), by reopening
	// its own conversation. A move asked for mid-turn runs at its next IDLE.
	SwitchAgent(context.Context, *connect.Request[v1.SwitchAgentRequest]) (*connect.Response[v1.SwitchAgentResponse], error)
	// Reopen a stopped agent's conversation, with a new task or as it was.
	ResumeAgent(context.Context, *connect.Request[v1.ResumeAgentRequest]) (*connect.Response[v1.ResumeAgentResponse], error)
	// Stop an agent's process on purpose and keep its conversation: RETIRED, its token revoked, its worktree and
	// branch kept. A message to it, or ResumeAgent, brings it back. Its parent or a device.
	RetireAgent(context.Context, *connect.Request[v1.RetireAgentRequest]) (*connect.Response[v1.RetireAgentResponse], error)
	// Stop a run: retire every agent in it and close it. A clean worktree is removed, and its branch with it unless
	// it moved past the commit it started at, or was pushed; a worktree with uncommitted changes stays.
	StopRun(context.Context, *connect.Request[v1.StopRunRequest]) (*connect.Response[v1.StopRunResponse], error)
	// Store a message for an agent and ring its doorbell. An agent sends only to its parent or its children.
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest]) (*connect.Response[v1.SendMessageResponse], error)
	// The calling agent's messages; unread ones are marked read unless peek is set.
	ReadInbox(context.Context, *connect.Request[v1.ReadInboxRequest]) (*connect.Response[v1.ReadInboxResponse], error)
	// The stored messages of a run, oldest first, for a device to read (ReadInbox is an agent's own mailbox). A
	// page ends at `limit`; `more` says there are further messages after the last one, whose id is the next
	// page's `after_id`.
	ListMessages(context.Context, *connect.Request[v1.ListMessagesRequest]) (*connect.Response[v1.ListMessagesResponse], error)
	// What waits on the user (what `bin/mesh status` calls waiting rows, for a person): a plan or a question sent
	// to an open run's lead that nobody has answered since, from an agent that is still there to hear the answer,
	// and every agent stopped at a prompt in its terminal. Oldest first, plans and questions before prompts. A
	// lead reads its own run's.
	ListWaiting(context.Context, *connect.Request[v1.ListWaitingRequest]) (*connect.Response[v1.ListWaitingResponse], error)
	// The event log from a cursor, then live. The first message is a Snapshot or a Resumed; only an End message
	// ends the stream, so a client resumes from its cursor after any other close.
	SubscribeEvents(context.Context, *connect.Request[v1.SubscribeEventsRequest], *connect.ServerStream[v1.SubscribeEventsResponse]) error
	// The host's settings (the policy: tiers, reviewers, caps, …) with their defaults and schemas, every one whose
	// key starts with the prefix. Agents read the policy they run under.
	ListSettings(context.Context, *connect.Request[v1.ListSettingsRequest]) (*connect.Response[v1.ListSettingsResponse], error)
	// Set a setting. The value must fit its schema; a key no setting has is NotFound.
	SetSetting(context.Context, *connect.Request[v1.SetSettingRequest]) (*connect.Response[v1.SetSettingResponse], error)
	// Put a setting back to its default.
	ResetSetting(context.Context, *connect.Request[v1.ResetSettingRequest]) (*connect.Response[v1.ResetSettingResponse], error)
	// A hook of the calling agent's CLI fired. Called by `meshctl hook`, never by hand.
	ReportHook(context.Context, *connect.Request[v1.ReportHookRequest]) (*connect.Response[v1.ReportHookResponse], error)
	// A one-time ticket for an agent's terminal WebSocket. Input is granted only with the terminal.input right.
	OpenTerminal(context.Context, *connect.Request[v1.OpenTerminalRequest]) (*connect.Response[v1.OpenTerminalResponse], error)
	// Create a one-time pairing token and QR/link payload for pairing a new device. Only the host's own device
	// may call this.
	CreatePairing(context.Context, *connect.Request[v1.CreatePairingRequest]) (*connect.Response[v1.CreatePairingResponse], error)
	// List paired devices. Only the host's own device may call this.
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	// Revoke a paired device's token and close its active streams. Only the host's own device may call this.
	RevokeDevice(context.Context, *connect.Request[v1.RevokeDeviceRequest]) (*connect.Response[v1.RevokeDeviceResponse], error)
}

// NewMeshServiceHandler builds an HTTP handler from the service implementation. It returns the path
// on which to mount the handler and the handler itself.
